{
  "verse_id": "5.39.1",
  "sarga": 39,
  "verse": "1",
  "ambiguous_marker": false,
  "sanskrit_iast": "maṇiṃ dattvā tataḥ sītā hanūmantam athābravīt । abhijñānam abhijñātam etad rāmasya tattvataḥ ॥1॥",
  "leonov_ru": "Отдав драгоценный камень, Сита Хануману тогда сказала: «Знак-примета будет узнан этот Рамой в самом деле».",
  "commentary": {
    "tilaka": "रामस्याभिज्ञातम् रामेणाभिज्ञातमित्यर्थः",
    "bhusana": "मणिं दत्त्वा ततः सीता हनुमन्तमथाब्रवीति ।\n\nअभिज्ञानमभिज्ञातमेतद्रामस्य तत्त्वतः\nमणिमित्यादि । अभिज्ञातं सम्यक् ज्ञातम्"
  },
  "pratika_check": {
    "tilaka": {
      "pratika_iast": "ranasyabhijnatan ranenabhijnatanityarthah",
      "matches_verse": true
    },
    "bhusana": {
      "pratika_iast": "nanin dattva tatah sita",
      "matches_verse": true
    }
  }
}
